class Solution {
public:
    string gameResult(ListNode* head) {
        int even = 0, odd = 0;
        ListNode* curr = head;
        while (curr) {
            if (curr->val > curr->next->val) even++;
            else if (curr->next->val > curr->val) odd++;
            curr = curr->next->next;
        }
        if (even > odd) return "Even";
        if (odd > even) return "Odd";
        return "Tie";
    }
};

class Solution {
    public String gameResult(ListNode head) {
        int even = 0, odd = 0;
        ListNode curr = head;
        while (curr != null) {
            if (curr.val > curr.next.val) even++;
            else if (curr.next.val > curr.val) odd++;
            curr = curr.next.next;
        }
        if (even > odd) return "Even";
        if (odd > even) return "Odd";
        return "Tie";
    }
}

